    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case ActionColumnConfig actionColumnConfig:
                if (actionColumnConfig != ActionColumnConfig)
                {
                    ActionColumnConfig = actionColumnConfig;
                    ModifiedParameters[nameof(ActionColumnConfig)] = ActionColumnConfig;
                }
                
                return true;
            case AttributeTableTemplate attributeTableTemplate:
                if (attributeTableTemplate != AttributeTableTemplate)
                {
                    AttributeTableTemplate = attributeTableTemplate;
                    ModifiedParameters[nameof(AttributeTableTemplate)] = AttributeTableTemplate;
                }
                
                return true;
            case Geometry filterGeometry:
                if (filterGeometry != FilterGeometry)
                {
                    FilterGeometry = filterGeometry;
                    ModifiedParameters[nameof(FilterGeometry)] = FilterGeometry;
                }
                
                return true;
            case TableTemplate tableTemplate:
                if (tableTemplate != TableTemplate)
                {
                    TableTemplate = tableTemplate;
                    ModifiedParameters[nameof(TableTemplate)] = TableTemplate;
                }
                
                return true;
            case TimeExtent timeExtent:
                if (timeExtent != TimeExtent)
                {
                    TimeExtent = timeExtent;
                    ModifiedParameters[nameof(TimeExtent)] = TimeExtent;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case ActionColumnConfig _:
                ActionColumnConfig = null;
                ModifiedParameters[nameof(ActionColumnConfig)] = ActionColumnConfig;
                return true;
            case AttributeTableTemplate _:
                AttributeTableTemplate = null;
                ModifiedParameters[nameof(AttributeTableTemplate)] = AttributeTableTemplate;
                return true;
            case Geometry _:
                FilterGeometry = null;
                ModifiedParameters[nameof(FilterGeometry)] = FilterGeometry;
                return true;
            case TableTemplate _:
                TableTemplate = null;
                ModifiedParameters[nameof(TableTemplate)] = TableTemplate;
                return true;
            case TimeExtent _:
                TimeExtent = null;
                ModifiedParameters[nameof(TimeExtent)] = TimeExtent;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        ActionColumnConfig?.ValidateRequiredGeneratedChildren();
        AttributeTableTemplate?.ValidateRequiredGeneratedChildren();
        FilterGeometry?.ValidateRequiredGeneratedChildren();
        TableTemplate?.ValidateRequiredGeneratedChildren();
        TimeExtent?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
